utomationColSurface:{en:"Surface",yue:"介面"},automationColVerb:{en:"Verb",yue:"指令"},automationColState:{en:"State",yue:"狀態"},automationStateInterfaceOnly:{en:"in the interface only",yue:"淨係喺介面度有"},automationStateNotImplemented:{en:"not implemented",yue:"未做"},ticketsSub:{en:"The recovery route if you ever lock yourself out of your own copy.",yue:"萬一你自己鎖咗自己出局，呢度就係返返嚟嘅路。"},ticketsPrivacyNote:{en:"Nothing here is sent anywhere. No ticket exists outside this computer, no network request is made, no data is collected, and nobody is reading it. This is a local recovery flow wearing a costume.",yue:"呢度嘅嘢乜都唔會寄去邊。冇工單存在喺呢部機以外，冇網絡請求，冇收集資料，亦都冇人喺度睇。呢個係扮成客服嘅本機還原流程啫。"},ticketsNewTitle:{en:"Open a ticket",yue:"開新工單"},ticketsCategoryLabel:{en:"Category",yue:"分類"},ticketsSeverityLabel:{en:"Severity",yue:"嚴重程度"},ticketsDescLabel:{en:"What happened?",yue:"發生咗咩事？"},ticketsSubmit:{en:"Submit ticket",yue:"提交工單"},ticketsCatTab:{en:"Locked out of a tab",yue:"俾分頁鎖咗出局"},ticketsCatSetting:{en:"Locked out of a setting",yue:"俾設定鎖咗出局"},ticketsCatPassword:{en:"Forgot a password",yue:"唔記得咗密碼"},ticketsCatAuthenticator:{en:"Lost an authenticator",yue:"遺失咗驗證器"},ticketsCatOther:{en:"Something else",yue:"其他問題"},severityLow:{en:"Low",yue:"低"},severityNormal:{en:"Normal",yue:"一般"},severityHigh:{en:"High",yue:"高"},severityCritical:{en:"Critical",yue:"緊急"},severityCatastrophic:{en:"Catastrophic",yue:"災難級"},ticketsWorkingTitle:{en:"The thing that actually works",yue:"真正有用嘅嘢"},ticketsWorkingBody:{en:"Deleting the application-data folder clears every lock and every setting. That is the documented recovery route, and it is the only one.",yue:"刪除應用程式資料夾就會清晒所有鎖同設定。呢個係有記錄在案嘅還原方法，亦係唯一嘅一個。"},ticketsOpenFolder:{en:"Open that folder",yue:"開返個資料夾"},ticketsOpenFolderNote:{en:"This opens the folder and stops there. The deleting is yours to do, in your own file manager.",yue:"呢個掣淨係幫你開個資料夾，之後就冇喇。刪嘅嘢要你自己喺檔案總管度做。"},ticketsYourTickets:{en:"Your tickets",yue:"你嘅工單"},ticketsAskUpdate:{en:"Ask for an update",yue:"追問進度"},ticketsSea